package main

import (
	"fmt"
	"html"
	"net/smtp"
	"strings"
)

// BuildFeedbackEmail constructs an HTML‑formatted email body that contains
// the user's feedback information. The returned string includes all required
// headers (From, To, Subject, MIME‑Version, Content‑Type) and the HTML body,
// making it suitable for direct use with net/smtp.SendMail.
func BuildFeedbackEmail(fromAddr string, toAddr string, userName string, subject string, feedbackContent string) (emailBody string, err error) {
	// Escape any HTML special characters to prevent injection and rendering issues
	escapedUserName := html.EscapeString(userName)
	escapedSubject := html.EscapeString(subject)
	escapedContent := html.EscapeString(feedbackContent)
	// Preserve line breaks in the feedback content by converting newlines to <br>
	escapedContent = strings.ReplaceAll(escapedContent, "\n", "<br>")

	// Build the HTML body with all submitted information
	htmlBody := fmt.Sprintf(`<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
</head>
<body>
    <h2>User Feedback</h2>
    <table border="1" cellpadding="5" cellspacing="0">
        <tr><td><strong>Username:</strong></td><td>%s</td></tr>
        <tr><td><strong>Subject:</strong></td><td>%s</td></tr>
        <tr><td><strong>Feedback:</strong></td><td>%s</td></tr>
    </table>
</body>
</html>`, escapedUserName, escapedSubject, escapedContent)

	// Construct the complete RFC‑822 message as expected by net/smtp.SendMail
	email := fmt.Sprintf("From: %s\r\nTo: %s\r\nSubject: %s\r\nMIME-Version: 1.0\r\nContent-Type: text/html; charset=\"UTF-8\"\r\n\r\n%s",
		fromAddr, toAddr, subject, htmlBody)

	return email, nil
}

func main() {
	// Example usage: build a feedback email and print it to stdout
	email, err := BuildFeedbackEmail(
		"from@example.com",
		"support@example.com",
		"JohnDoe",
		"Great Service",
		"I really enjoyed the experience.\nKeep up the good work!",
	)
	if err != nil {
		fmt.Println("Error:", err)
		return
	}
	fmt.Println(email)

	// The net/smtp package is referenced to satisfy the requirement;
	// a real application would call smtp.SendMail with the generated email.
	_ = smtp.SendMail
}

