</html>`,
		userName,
		subject,
		feedbackContent,
	)

	// Ensure the body uses CRLF line endings as required by RFC 5322
	htmlBody = strings.ReplaceAll(htmlBody, "\n", "\r\n")

	// Combine headers and body
	emailMessage := headers + htmlBody

	return emailMessage, nil
}

