var _ = smtp.SendMail

// BuildFeedbackEmail generates an HTML email body containing user feedback information.
// The returned string is a complete RFC 822 message ready to be sent via net/smtp.SendMail.
func BuildFeedbackEmail(fromAddr string, toAddr string, userName string, subject string, feedbackContent string) (emailBody string, err error) {
    // Trim whitespace
    fromAddr = strings.TrimSpace(fromAddr)
    toAddr = strings.TrimSpace(toAddr)
    userName = strings.TrimSpace(userName)
    subject = strings.TrimSpace(subject)
    feedbackContent = strings.TrimSpace(feedbackContent)

    // Validate required fields
    if fromAddr == "" {
        return "", fmt.Errorf("from address cannot be empty")
    }
    if toAddr == "" {
        return "", fmt.Errorf("to address cannot be empty")
    }
    if userName == "" {
        return "", fmt.Errorf("user name cannot be empty")
    }
    if subject == "" {
        return "", fmt.Errorf("subject cannot be empty")
    }
    if feedbackContent == "" {
        return "", fmt.Errorf("feedback content cannot be empty")
    }

    // Sanitize header values to prevent injection attacks
    sanitize := func(s string) string {
        s = strings.ReplaceAll(s, "\r", "")
        s = strings.ReplaceAll(s, "\n", "")
        return s
    }
    fromAddr = sanitize(fromAddr)
    toAddr = sanitize(toAddr)
    subject = sanitize(subject)

    // Escape HTML entities to prevent XSS in the email client
    escapedUserName := html.EscapeString(userName)
    escapedSubject := html.EscapeString(subject)
    escapedContent := html.EscapeString(feedbackContent)

    // Preserve line breaks in the feedback content
    escapedContent = strings.ReplaceAll(escapedContent, "\r\n", "<br>\n")
    escapedContent = strings.ReplaceAll(escapedContent, "\n", "<br>\n")

    // Build the HTML body
    htmlBody := fmt.Sprintf(`<html>
<body>
    <h2>User Feedback</h2>
    <p><strong>User Name:</strong> %s</p>
    <p><strong>Subject:</strong> %s</p>
    <hr>
    <p><strong>Feedback Content:</strong></p>
    <p>%s</p>
</body>
</html>`, escapedUserName, escapedSubject, escapedContent)

    // Construct the full RFC 822 message, which aligns with the format expected by net/smtp.
    msg := fmt.Sprintf("From: %s\r\nTo: %s\r\nSubject: %s\r\nMIME-Version: 1.0\r\nContent-Type: text/html; charset=\"UTF-8\"\r\n\r\n%s",
        fromAddr, toAddr, subject, htmlBody)

    return msg, nil
}

