import (
	"bytes"
	"errors"
	"html/template"
)

const emailTemplate = `From: {{.From}}
To: {{.To}}
Subject: {{.Subject}}
MIME-Version: 1.0
Content-Type: text/html; charset="UTF-8"

<html>
<body>
<h2>User Feedback</h2>
<p><strong>Username:</strong> {{.UserName}}</p>
<p><strong>Subject:</strong> {{.Subject}}</p>
<p><strong>Feedback:</strong></p>
<pre>{{.FeedbackContent}}</pre>
</body>
</html>
`

// EmailData holds the fields to be inserted into the email template.
type EmailData struct {
	From            string
	To              string
	Subject         string
	UserName        string
	FeedbackContent string
}

// BuildFeedbackEmail constructs an HTML email body containing user feedback information.
// It returns the complete email (headers + body) as a string, ready for sending via SMTP.
func BuildFeedbackEmail(fromAddr string, toAddr string, userName string, subject string, feedbackContent string) (emailBody string, err error) {
	if fromAddr == "" || toAddr == "" {
		return "", errors.New("fromAddr and toAddr cannot be empty")
	}

	data := EmailData{
		From:            fromAddr,
		To:              toAddr,
		Subject:         subject,
		UserName:        userName,
		FeedbackContent: feedbackContent,
	}

	t, err := template.New("email").Parse(emailTemplate)
	if err != nil {
		return "", err
	}

	var buf bytes.Buffer
	if err := t.Execute(&buf, data); err != nil {
		return "", err
	}

	return buf.String(), nil
}

// Optional main function to demonstrate the usage.
func main() {
	email, err := BuildFeedbackEmail(
		"user@example.com",
		"support@example.com",
		"JaneDoe",
		"Great service!",
		"I really appreciate the quick response.",
	)
	if err != nil {
		panic(err)
	}
	println(email)
}

