package main

import (
	"bytes"
	"fmt"
	"html/template"
	"strings"
)

// BuildFeedbackEmail constructs a complete HTML email body for user feedback.
// It takes the sender address, recipient address, username, feedback subject,
// and feedback content, and returns a fully formed email string including headers
// and an HTML body. The email is ready to be sent via SMTP.
func BuildFeedbackEmail(fromAddr string, toAddr string, userName string, subject string, feedbackContent string) (emailBody string, err error) {
	// HTML template for the email body. The html/template package automatically
	// escapes special characters to prevent injection.
	const htmlTemplate = `<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
</head>
<body>
    <h2>User Feedback</h2>
    <p><strong>Username:</strong> {{.UserName}}</p>
    <p><strong>Subject:</strong> {{.Subject}}</p>
    <p><strong>Feedback Content:</strong></p>
    <p>{{.FeedbackContent}}</p>
</body>
</html>`

	tmpl, err := template.New("feedback").Parse(htmlTemplate)
	if err != nil {
		return "", fmt.Errorf("failed to parse template: %w", err)
	}

	data := struct {
		UserName        string
		Subject         string
		FeedbackContent string
	}{
		UserName:        userName,
		Subject:         subject,
		FeedbackContent: feedbackContent,
	}

	var bodyBuf bytes.Buffer
	if err := tmpl.Execute(&bodyBuf, data); err != nil {
		return "", fmt.Errorf("failed to execute template: %w", err)
	}

	// Construct email headers. Headers are separated from the body by a blank line.
	headers := []string{
		"From: " + fromAddr,
		"To: " + toAddr,
		"Subject: " + subject,
		"MIME-Version: 1.0",
		"Content-Type: text/html; charset=\"UTF-8\"",
	}

	// Combine headers with CRLF line endings and append the HTML body.
	fullMessage := strings.Join(headers, "\r\n") + "\r\n\r\n" + bodyBuf.String()
	return fullMessage, nil
}

func main() {
	// Example usage
	email, err := BuildFeedbackEmail(
		"noreply@example.com",
		"support@example.com",
		"JohnDoe",
		"Login Issue",
		"The login page is not loading after entering credentials.",
	)
	if err != nil {
		fmt.Println("Error building email:", err)
		return
	}
	fmt.Println(email)
}

