// BuildFeedbackEmail creates an HTML email body containing user feedback.
// The returned message complies with the format expected by net/smtp.SendMail.
func BuildFeedbackEmail(fromAddr string, toAddr string, userName string, subject string, feedbackContent string) (string, error) {
	// Escape user-provided strings for safe HTML inclusion
	escUserName := html.EscapeString(userName)
	escSubject := html.EscapeString(subject)
	escContent := html.EscapeString(feedbackContent)
	// Convert newlines to <br> for HTML display
	escContent = strings.ReplaceAll(escContent, "\r\n", "<br>")
	escContent = strings.ReplaceAll(escContent, "\n", "<br>")

	// Email subject line
	emailSubject := fmt.Sprintf("User Feedback from %s: %s", escUserName, escSubject)

	// Build email headers compliant with net/smtp.SendMail format
	headers := fmt.Sprintf("From: %s\r\nTo: %s\r\nSubject: %s\r\nMIME-Version: 1.0\r\nContent-Type: text/html; charset=\"UTF-8\"\r\n\r\n",
		fromAddr, toAddr, emailSubject)

	// HTML body with feedback details
	body := fmt.Sprintf(`<!DOCTYPE html>
<html>
<head><meta charset="UTF-8"></head>
<body>
    <h2>User Feedback</h2>
    <p><strong>User Name:</strong> %s</p>
    <p><strong>Feedback Subject:</strong> %s</p>
    <p><strong>Feedback Content:</strong></p>
    <div>%s</div>
</body>
</html>`, escUserName, escSubject, escContent)

	return headers + body, nil
}

func main() {
	email, err := BuildFeedbackEmail(
		"noreply@example.com",
		"support@example.com",
		"John Doe",
		"Great product!",
		"I really love the new features. Keep up the good work!\nThanks.",
