// BuildFeedbackEmail constructs an HTML formatted email body containing user feedback.
func BuildFeedbackEmail(fromAddr, toAddr, userName, subject, feedbackContent string) (string, error) {
	// Validate inputs
	if fromAddr == "" || toAddr == "" || userName == "" || subject == "" || feedbackContent == "" {
		return "", fmt.Errorf("all inputs must be non-empty")
	}

	// Sanitize headers to prevent injection
	sanitize := func(s string) string {
		return strings.NewReplacer("\r\n", "", "\n", "").Replace(s)
	}
	fromAddr = sanitize(fromAddr)
	toAddr = sanitize(toAddr)
	userName = sanitize(userName)
	subject = sanitize(subject)

	// Escape HTML content
	escape := func(s string) string {
		return strings.NewReplacer("&", "&amp;", "<", "&lt;", ">", "&gt;", "\"", "&#34;", "'", "&#39;").Replace(s)
	}
	escapedUser := escape(userName)
	escapedSubject := escape(subject)
	escapedContent := escape(feedbackContent)

	// Build email body (SMTP message)
	headers := fmt.Sprintf("From: %s\r\nTo: %s\r\nSubject: Feedback: %s\r\nMIME-Version: 1.0\r\nContent-Type: text/html; charset=\"UTF-8\"\r\n\r\n",
