	htmlBody := fmt.Sprintf(`<html>
<body>
    <h2>User Feedback</h2>
    <p><strong>Username:</strong> %s</p>
    <p><strong>Subject:</strong> %s</p>
    <hr>
    <p><strong>Feedback:</strong></p>
    <p>%s</p>
</body>
</html>`, escapedUser, escapedSubject, escapedContent)

	return headers + htmlBody, nil
}

func main() {
	from := "feedback@example.com"
	to := "support@example.com"
	userName := "Jane Doe"
	subject := "Suggestion"
	feedback := "I think you should add dark mode."

	emailBody, err := BuildFeedbackEmail(from, to, userName, subject, feedback)
	if err != nil {
		fmt.Printf("Failed to build email: %v\n", err)
		return
	}

	fmt.Println("=== Generated Email ===")
	fmt.Println(emailBody)

	// Example: Sending the email using net/smtp
	// Set up authentication information.
	auth := smtp.PlainAuth("", "user@example.com", "password", "smtp.example.com")
	// Send the email.
	err = smtp.SendMail("smtp.example.com:587", auth, from, []string{to}, []byte(emailBody))
	if err != nil {
		fmt.Printf("Failed to send email: %v\n", err)
	} else {
		fmt.Println("Email sent successfully!")
	}
}

