package main

import (
    "errors"
    "fmt"
    "net/smtp"
)

// BuildFeedbackEmail constructs an HTML email body for user feedback.
// It returns the complete RFC 2822 formatted message (headers + body) ready to be sent via SMTP,
// or an error if any required field is empty.
func BuildFeedbackEmail(fromAddr string, toAddr string, userName string, subject string, feedbackContent string) (string, error) {
    if fromAddr == "" || toAddr == "" || userName == "" || subject == "" || feedbackContent == "" {
        return "", errors.New("all fields are required")
    }

    // Prepare email headers
    headers := make(map[string]string)
    headers["From"] = fromAddr
